select  from course_homework_template
where course_id = #{courseId}
order by case when day_number is null then 0 else day_number end, stage_name, id

select count(*) from course_homework_template
where course_id = #{courseId} and teaching_mode = #{teachingMode}

    and stage_name = #{stageName}
    and day_number = #{dayNumber}

and id != #{excludeId}
